ejemplo_bien:
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE reserva (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  recurso_id bigint NOT NULL,
  franja tstzrange NOT NULL CHECK (NOT isempty(franja)),
  estado text NOT NULL DEFAULT 'pendiente'
    CHECK (estado IN ('pendiente','confirmada','liberada','cancelada')),
  CONSTRAINT ex_reserva_vigente_sin_solape EXCLUDE USING gist (recurso_id WITH =, franja WITH &&)
    WHERE (estado NOT IN ('liberada','cancelada'))
);
